from AlgorithmImports import *
from datetime import timedelta


class FiveMinuteSpyCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        spy_security = self.AddEquity("SPY", Resolution.Minute)
        spy_security.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = spy_security.Symbol

        option_security = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = option_security.Symbol
        option_security.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(timedelta(days=0), timedelta(days=730))
        )

        self.five_minute_closes = []
        self.minute_bucket_end = None
        self.minute_bucket = {}

        self.held_contract = None
        self.pending_contract = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.entry_fill_price = None
        self.expiration_block_date = None

    def OnData(self, data: Slice):
        # Assignment/exercise protection: never retain SPY shares created by options.
        if self.Portfolio[self.spy].Invested:
            quantity = self.Portfolio[self.spy].Quantity
            if quantity != 0:
                self.Debug(f"Unexpected SPY exercise/assignment exposure; liquidating {quantity} shares.")
                self.MarketOrder(self.spy, -quantity)
            return

        self._handle_open_option_position(data)
        self._update_five_minute_bars_and_evaluate_entry(data)

    def _update_five_minute_bars_and_evaluate_entry(self, data: Slice):
        spy_bar = data.Bars.get(self.spy)
        if spy_bar is None:
            return

        end_time = spy_bar.EndTime
        if not self._is_regular_session_minute(end_time):
            return

        bucket_end = self._five_minute_boundary(end_time)

        if self.minute_bucket_end != bucket_end:
            self.minute_bucket_end = bucket_end
            self.minute_bucket = {}

        self.minute_bucket[end_time] = spy_bar

        if end_time != bucket_end:
            return

        expected_times = [bucket_end - timedelta(minutes=i) for i in range(4, -1, -1)]
        if not all(t in self.minute_bucket for t in expected_times):
            # A five-minute interval was incomplete: do not synthesize a bar.
            self.minute_bucket = {}
            return

        close = self.minute_bucket[bucket_end].Close
        self.minute_bucket = {}

        previous_fast = None
        previous_slow = None
        if len(self.five_minute_closes) >= 20:
            previous_fast = sum(self.five_minute_closes[-5:]) / 5.0
            previous_slow = sum(self.five_minute_closes[-20:]) / 20.0

        self.five_minute_closes.append(close)
        if len(self.five_minute_closes) > 20:
            self.five_minute_closes.pop(0)

        if len(self.five_minute_closes) < 20 or previous_fast is None:
            return

        current_fast = sum(self.five_minute_closes[-5:]) / 5.0
        current_slow = sum(self.five_minute_closes[-20:]) / 20.0
        bullish_cross = previous_fast <= previous_slow and current_fast > current_slow

        if not bullish_cross or not self._is_entry_time(bucket_end):
            return

        self._try_enter_call(data)

    def _try_enter_call(self, data: Slice):
        if self.expiration_block_date == self.Time.date():
            return

        if self.Portfolio[self.spy].Invested or self.held_contract is not None:
            return

        if self._ticket_is_open(self.entry_ticket) or self._ticket_is_open(self.exit_ticket):
            return

        chain = data.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Entry skipped: no SPY option chain in current Slice.")
            return

        algorithm_date = self.Time.date()
        eligible_expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= algorithm_date + timedelta(days=7)
        })

        if not eligible_expirations:
            self.Debug("Entry skipped: no SPY expiration at least seven calendar days away.")
            return

        selected_expiry = eligible_expirations[0]
        spy_price = self.Securities[self.spy].Price
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no qualifying call at selected expiration.")
            return

        selected = sorted(candidates, key=lambda c: (c.Strike, str(c.Symbol)))[0]

        self.pending_contract = selected.Symbol
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = self.entry_ticket.OrderId
        self.Debug(
            f"Entry submitted: {selected.Symbol}, expiry {selected.Expiry.date()}, "
            f"strike {selected.Strike}."
        )

    def _handle_open_option_position(self, data: Slice):
        if self.held_contract is None:
            return

        holding = self.Portfolio[self.held_contract]
        if not holding.Invested:
            if not self._ticket_is_open(self.exit_ticket):
                self.held_contract = None
                self.entry_fill_price = None
            return

        expiry_date = self.held_contract.ID.Date.date()

        # Expiration-day protection. Block all replacements on that date.
        if self.Time.date() >= expiry_date:
            self.expiration_block_date = self.Time.date()
            self._submit_exit("expiration processing")
            return

        preceding_trading_day = self._previous_trading_day(expiry_date)
        if self.Time.date() == preceding_trading_day:
            if self.Time.hour == 15 and self.Time.minute == 45:
                self._submit_exit("15:45 pre-expiration time stop")
                return

        if self._ticket_is_open(self.exit_ticket) or self.entry_fill_price is None:
            return

        quote = data.QuoteBars.get(self.held_contract)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_fill_price * 1.50:
            self._submit_exit(
                f"50% profit target reached (midpoint {midpoint:.2f}, "
                f"entry {self.entry_fill_price:.2f})"
            )

    def _submit_exit(self, reason: str):
        if self.held_contract is None or self._ticket_is_open(self.exit_ticket):
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        # Ensure a newly submitted exit is the only open exit order.
        for order in self.Transactions.GetOpenOrders(self.held_contract):
            self.Transactions.CancelOrder(order.Id)

        self.exit_ticket = self.MarketOrder(self.held_contract, -quantity)
        self.exit_order_id = self.exit_ticket.OrderId
        self.Debug(f"Exit submitted: {self.held_contract}; {reason}.")

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_order_id is not None and order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.held_contract = self.pending_contract
                self.entry_fill_price = order_event.FillPrice
                self.entry_ticket = None
                self.entry_order_id = None
                self.pending_contract = None
                self.Debug(
                    f"Entry filled: {self.held_contract} at {self.entry_fill_price:.2f}."
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.Debug(f"Entry order did not complete: {order_event.Status}.")
                self.entry_ticket = None
                self.entry_order_id = None
                self.pending_contract = None

        if self.exit_order_id is not None and order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exit filled: {self.held_contract} at {order_event.FillPrice:.2f}."
                )
                self.exit_ticket = None
                self.exit_order_id = None
                if self.held_contract is not None and not self.Portfolio[self.held_contract].Invested:
                    self.held_contract = None
                    self.entry_fill_price = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.Debug(f"Exit order did not complete: {order_event.Status}.")
                self.exit_ticket = None
                self.exit_order_id = None

    def _previous_trading_day(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate, False):
            candidate -= timedelta(days=1)

        return candidate

    @staticmethod
    def _five_minute_boundary(time):
        return time + timedelta(minutes=(5 - time.minute % 5) % 5)

    @staticmethod
    def _is_regular_session_minute(end_time):
        minute_of_day = end_time.hour * 60 + end_time.minute
        return 9 * 60 + 31 <= minute_of_day <= 16 * 60

    @staticmethod
    def _is_entry_time(end_time):
        minute_of_day = end_time.hour * 60 + end_time.minute
        return 9 * 60 + 45 <= minute_of_day <= 14 * 60 + 30

    @staticmethod
    def _ticket_is_open(ticket):
        if ticket is None:
            return False

        return ticket.Status not in [
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ]
