        self.held_contract = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.entry_fill_price = None
        self.expiration_date = None
        self.expiration_blocked_date = None

    def SetOptionFilter(self):
        option = self.Securities[self.option_symbol]
        option.SetFilter(-100, 100, timedelta(0), timedelta(days=365))

    def OnData(self, slice):
        self._handle_unexpected_equity_position()

        if self._has_open_option_position():
            self._process_expiration_safety()
            self._process_option_exits(slice)

        if not slice.Bars.ContainsKey(self.spy):
            return

        self._update_five_minute_builder(slice.Bars[self.spy], slice)

    def _update_five_minute_builder(self, minute_bar, slice):
        end_time = minute_bar.EndTime
        current_bucket_end = self._five_minute_bucket_end(end_time)

        if self.bucket_end is not None and current_bucket_end != self.bucket_end:
            # A new interval started before the prior interval completed.
            # Discard the incomplete interval without updating indicators.
            self.bucket_end = None
            self.bucket_bars = []
            self.bucket_times = []

        if self.bucket_end is None:
            self.bucket_end = current_bucket_end

        self.bucket_bars.append(minute_bar)
        self.bucket_times.append(end_time)

        if end_time != self.bucket_end:
            return

        complete = self._is_complete_five_minute_interval()

        if complete:
            close = self.bucket_bars[-1].Close
            completed_bar_end = self.bucket_end
            self._process_completed_five_minute_bar(completed_bar_end, close, slice)

        self.bucket_end = None
        self.bucket_bars = []
        self.bucket_times = []

    def _five_minute_bucket_end(self, time):
        minute_of_day = time.hour * 60 + time.minute
        rounded = ((minute_of_day + 4) // 5) * 5

        return time.replace(
            hour=rounded // 60,
            minute=rounded % 60,
            second=0,
            microsecond=0
        )

    def _is_complete_five_minute_interval(self):
        if len(self.bucket_bars) != 5:
            return False

        expected_times = [
            self.bucket_end - timedelta(minutes=4),
            self.bucket_end - timedelta(minutes=3),
            self.bucket_end - timedelta(minutes=2),
            self.bucket_end - timedelta(minutes=1),
            self.bucket_end
        ]

        return self.bucket_times == expected_times

    def _process_completed_five_minute_bar(self, bar_end, close, slice):
        previous_ready = self.fast.IsReady and self.slow.IsReady
        previous_fast = self.fast.Current.Value
        previous_slow = self.slow.Current.Value

        point = IndicatorDataPoint(bar_end, close)
        self.fast.Update(point)
        self.slow.Update(point)

        bullish_crossover = (
            previous_ready
            and self.fast.IsReady
            and self.slow.IsReady
            and previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        if not bullish_crossover:
            return

        bar_time = bar_end.time()
        if bar_time < TimeSpan(9, 45, 0) or bar_time > TimeSpan(14, 30, 0):
            return

        if self.expiration_blocked_date == self.Time.date():
            return

        if self.Portfolio.Invested or self._entry_order_open():
            return

        self._enter_call_from_current_chain(slice)

    def _enter_call_from_current_chain(self, slice):
        if not slice.OptionChains.ContainsKey(self.option_symbol):
            self.Debug("Entry skipped: no SPY option chain in current Slice.")
            return

        chain = slice.OptionChains[self.option_symbol]
        algorithm_date = self.Time.date()

        valid_expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if (contract.Expiry.date() - algorithm_date).days >= 7
        })

        if not valid_expirations:
            self.Debug("Entry skipped: no expiration at least 7 calendar days away.")
            return

        selected_expiration = valid_expirations[0]
        minimum_strike = self.Securities[self.spy].Price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiration
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no qualifying call at selected expiration.")
            return

        selected = min(candidates, key=lambda c: (c.Strike, str(c.Symbol)))

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.held_contract = selected.Symbol
        self.expiration_date = selected.Expiry.date()
        self.entry_fill_price = None

        self.Debug(
            f"Entry submitted: {selected.Symbol}, expiry {selected_expiration}, "
            f"strike {selected.Strike}"
        )

    def _process_option_exits(self, slice):
        if self.held_contract is None or self.entry_fill_price is None:
            return

        if self._exit_order_open():
            return

        if not slice.QuoteBars.ContainsKey(self.held_contract):
            return

        quote = slice.QuoteBars[self.held_contract]
        bid = quote.Bid.Close if quote.Bid is not None else 0
        ask = quote.Ask.Close if quote.Ask is not None else 0

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_fill_price * 1.50:
            self._submit_exit("50% profit target reached")

    def _process_expiration_safety(self):
        if self.held_contract is None or self.expiration_date is None:
            return

        today = self.Time.date()

        if today >= self.expiration_date:
            self.expiration_blocked_date = today
            if not self._exit_order_open():
                self._submit_exit("expiration-day safety liquidation")
            return

        previous_trading_day = self.Securities[self.spy].Exchange.Hours.GetPreviousTradingDay(
            datetime(self.expiration_date.year, self.expiration_date.month, self.expiration_date.day)
        ).date()

        if today == previous_trading_day and self.Time.hour == 15 and self.Time.minute == 45:
            if not self._exit_order_open():
                self._submit_exit("15:45 pre-expiration liquidation")

    def _submit_exit(self, reason):
        if self.held_contract is None or self._exit_order_open():
            return

        for order in self.Transactions.GetOpenOrders():
            if order.Symbol == self.held_contract:
                self.Transactions.CancelOrder(order.Id)

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(self.held_contract, -quantity)
        self.Debug(f"Exit submitted: {self.held_contract}; reason: {reason}")

    def _handle_unexpected_equity_position(self):
        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity != 0:
            self.Debug(
                f"Unexpected SPY equity position ({spy_quantity}) detected, "
                "liquidating possible exercise/assignment."
            )
            self.MarketOrder(self.spy, -spy_quantity)

    def _has_open_option_position(self):
        return (
            self.held_contract is not None
            and self.Portfolio[self.held_contract].Quantity != 0
        )

    def _entry_order_open(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

    def _exit_order_open(self):
        if self.exit_ticket is None:
            return False

        return self.exit_ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

    def OnOrderEvent(self, order_event):
        if getattr(order_event, "IsAssignment", False):
            self.Debug(f"Unexpected option exercise/assignment event: {order_event.Symbol}")

        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.entry_fill_price = order_event.FillPrice
                self.Debug(
                    f"Entry filled: {order_event.Symbol} at {self.entry_fill_price:.2f}"
                )
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.Debug(f"Entry canceled/invalid: {order_event.Symbol}")
                self.held_contract = None
                self.entry_fill_price = None
                self.expiration_date = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order_event.Symbol} at {order_event.FillPrice:.2f}")
                self.held_contract = None
                self.entry_fill_price = None
                self.expiration_date = None
