from collections import deque
from datetime import datetime, timedelta, time

from AlgorithmImports import *
from QuantConnect.Data.Consolidators import TradeBarConsolidator


class SpyFiveMinuteCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            data_normalization_mode=DataNormalizationMode.Raw
        ).Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        self.option_canonical = option.Symbol
        option.SetFilter(lambda universe: universe
                         .IncludeWeeklys()
                         .Strikes(-500, 500)
                         .Expiration(0, 365))

        self.closes = deque(maxlen=20)
        self.pending_entry_signal = False

        self.held_option = None
        self.held_expiry = None
        self.entry_price = None

        self.entry_ticket = None
        self.pending_entry_symbol = None
        self.exit_ticket = None

        self.expiration_block_date = None

        self.five_minute_consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.five_minute_consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, self.five_minute_consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        previous_fast = None
        previous_slow = None

        if len(self.closes) == 20:
            previous_slow = sum(self.closes) / 20.0
            previous_fast = sum(list(self.closes)[-5:]) / 5.0

        self.closes.append(bar.Close)

        if len(self.closes) != 20 or previous_fast is None:
            return

        current_slow = sum(self.closes) / 20.0
        current_fast = sum(list(self.closes)[-5:]) / 5.0

        bar_end_time = bar.EndTime.time()
        eligible_time = time(9, 45) <= bar_end_time <= time(14, 30)

        if (eligible_time
                and previous_fast <= previous_slow
                and current_fast > current_slow):
            self.pending_entry_signal = True

    def OnData(self, slice):
        self._handle_unexpected_spy_position()
        self._handle_expiration()
        self._cleanup_closed_position_state()

        if self.held_option is not None and self.Portfolio[self.held_option].Invested:
            self._evaluate_exits(slice)

        if self.pending_entry_signal:
            self.pending_entry_signal = False
            self._try_enter(slice)

    def _try_enter(self, slice):
        if self.expiration_block_date == self.Time.date():
            self.Debug("Skipped entry: expiration processing is active today.")
            return

        if self.held_option is not None and self.Portfolio[self.held_option].Invested:
            return

        if self.entry_ticket is not None:
            return

        if not slice.Bars.ContainsKey(self.spy):
            self.Debug("Skipped entry: SPY price is unavailable in this Slice.")
            return

        if not slice.OptionChains.ContainsKey(self.option_canonical):
            self.Debug("Skipped entry: no SPY option chain in this Slice.")
            return

        spy_price = slice.Bars[self.spy].Close
        chain = slice.OptionChains[self.option_canonical]
        today = self.Time.date()

        eligible_expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if (contract.Right == OptionRight.Call
                and (contract.Expiry.date() - today).days >= 7)
        })

        if not eligible_expiries:
            self.Debug("Skipped entry: no expiration at least 7 calendar days away.")
            return

        selected_expiry = eligible_expiries[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain
            if (contract.Right == OptionRight.Call
                and contract.Expiry.date() == selected_expiry
                and contract.Strike >= minimum_strike)
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call at the selected expiration.")
            return

        selected = min(candidates, key=lambda c: (c.Strike, str(c.Symbol)))

        self.pending_entry_symbol = selected.Symbol
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Entry submitted: {selected.Symbol}, expiry {selected_expiry}, "
            f"strike {selected.Strike}"
        )

    def _evaluate_exits(self, slice):
        if self.exit_ticket is not None:
            return

        holding = self.Portfolio[self.held_option]
        if not holding.Invested:
            return

        if self._is_day_before_expiry_at_time_stop():
            self._submit_exit("time stop before expiration")
            return

        if not slice.QuoteBars.ContainsKey(self.held_option):
            return

        quote = slice.QuoteBars[self.held_option]
        if quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if self.entry_price is not None and midpoint >= self.entry_price * 1.50:
            self._submit_exit("50% profit target")

    def _is_day_before_expiry_at_time_stop(self):
        if self.held_expiry is None or self.Time.time() < time(15, 45):
            return False

        next_open = self.Securities[self.spy].Exchange.Hours.GetNextMarketOpen(
            self.Time + timedelta(minutes=1),
            False
        )
        return next_open.date() == self.held_expiry.date()

    def _handle_expiration(self):
        if self.held_option is None or self.held_expiry is None:
            return

        if self.Time.date() >= self.held_expiry.date():
            self.expiration_block_date = self.Time.date()
            if self.Portfolio[self.held_option].Invested:
                self._submit_exit("expiration safety liquidation")

    def _handle_unexpected_spy_position(self):
        spy_holding = self.Portfolio[self.spy]

        if spy_holding.Invested:
            self.Debug("Unexpected SPY exercise/assignment position detected; liquidating.")
            self.MarketOrder(self.spy, -spy_holding.Quantity)

    def _submit_exit(self, reason):
        if self.held_option is None or self.exit_ticket is not None:
            return

        holding = self.Portfolio[self.held_option]
        if not holding.Invested:
            return

        for order in self.Transactions.GetOpenOrders(self.held_option):
            self.Transactions.CancelOrder(order.Id, "Replacing open exit order")

        self.exit_ticket = self.MarketOrder(self.held_option, -holding.Quantity)
        self.Debug(f"Exit submitted ({reason}): {self.held_option}")

    def _cleanup_closed_position_state(self):
        if self.held_option is None:
            return

        if not self.Portfolio[self.held_option].Invested and self.exit_ticket is None:
            self.held_option = None
            self.held_expiry = None
            self.entry_price = None

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.FillQuantity > 0:
                self.held_option = self.pending_entry_symbol
                self.held_expiry = self.held_option.ID.Date
                self.entry_price = order_event.FillPrice
                self.Debug(
                    f"Entry filled: {self.held_option} at {self.entry_price:.2f}"
                )

            if order_event.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
                if order_event.Status != OrderStatus.Filled:
                    self.Debug(f"Entry did not fill: {order_event.Status}")
                self.entry_ticket = None
                self.pending_entry_symbol = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order_event.Symbol} at {order_event.FillPrice:.2f}")
