        slow_current = sum(self.closes[i] for i in range(0, 20)) / 20.0
        fast_previous = sum(self.closes[i] for i in range(1, 6)) / 5.0
        slow_previous = sum(self.closes[i] for i in range(1, 21)) / 20.0

        is_bullish_cross = (
            fast_previous <= slow_previous and fast_current > slow_current
        )

        local_time = bar.end_time.time()
        eligible_time = (
            local_time >= datetime.strptime("09:45", "%H:%M").time()
