                )
                self.exit_order_id = None
                self.held_option = None
                self.held_expiry = None
                self.entry_price = None
            elif order_event.status in (OrderStatus.CANCELED, OrderStatus.INVALID):
                self.exit_order_id = None

        self._handle_unexpected_spy_position()

    def _is_pre_expiration_time_stop(self) -> bool:
        if self.held_expiry is None:
            return False

        previous_trading_day = self._previous_trading_day(self.held_expiry)
        return (
            self.time.date() == previous_trading_day
            and self.time.hour == 15
            and self.time.minute == 45
        )

    def _previous_trading_day(self, expiry_date):
        if expiry_date in self.previous_trading_day_cache:
            return self.previous_trading_day_cache[expiry_date]

        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.securities[self.spy].exchange.hours

        while not exchange_hours.is_date_open(candidate, False):
            candidate -= timedelta(days=1)

        self.previous_trading_day_cache[expiry_date] = candidate
        return candidate

    def _has_open_entry_order(self) -> bool:
        return self._is_order_open(self.entry_order_id)

    def _has_open_exit_order(self) -> bool:
        return self._is_order_open(self.exit_order_id)

    def _is_order_open(self, order_id) -> bool:
        if order_id is None:
            return False

        order = self.transactions.get_order_by_id(order_id)
        return (
            order is not None
            and order.status not in (
                OrderStatus.FILLED,
                OrderStatus.CANCELED,
                OrderStatus.INVALID
            )
        )

    def _handle_unexpected_spy_position(self):
        spy_quantity = self.portfolio[self.spy].quantity

        if spy_quantity != 0 and not self.spy_liquidation_pending:
            self.spy_liquidation_pending = True
            self.debug(
                "Unexpected SPY position from exercise/assignment; liquidating immediately."
            )
            self.market_order(self.spy, -spy_quantity, tag="Exercise/assignment cleanup")

        if spy_quantity == 0:
            self.spy_liquidation_pending = False
