from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta, time


class SpyFiveMinuteCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity("SPY", Resolution.Minute).Symbol
        self.Securities[self.spy].SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option_symbol = self.AddOption("SPY", Resolution.Minute).Symbol
        self.OptionChainProvider = self.OptionChainProvider
        self.SetSecurityInitializer(
            BrokerageModelSecurityInitializer(
                self.BrokerageModel,
                FuncSecuritySeeder(self.GetLastKnownPrices)
            )
        )

        # Broad enough to retain near-OTM calls with expirations well beyond 7 days.
        self.Securities[self.option_symbol].SetFilter(
            -100, 100, timedelta(days=0), timedelta(days=730)
        )

        self.close_history = deque(maxlen=21)
        self.pending_entry_signal = False

        self.held_contract = None
        self.held_expiry = None
        self.entry_price = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.expiration_block_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        # A prior fully-ready slow average is required, hence 21 actual bars.
        self.close_history.append(float(bar.Close))
        if len(self.close_history) < 21:
            return

        closes = list(self.close_history)
        previous_fast = sum(closes[-6:-1]) / 5.0
        previous_slow = sum(closes[-21:-1]) / 20.0
        current_fast = sum(closes[-5:]) / 5.0
        current_slow = sum(closes[-20:]) / 20.0

        bar_end = bar.EndTime.time()
        within_entry_window = time(9, 45) <= bar_end <= time(14, 30)

        if (
            within_entry_window
            and previous_fast <= previous_slow
            and current_fast > current_slow
        ):
            # OnData consumes this against the current Slice's option chain.
            self.pending_entry_signal = True

    def OnData(self, slice):
        self.HandleUnexpectedSpyHolding()

        # Never intentionally retain a contract into its expiration date.
        if self.held_contract is not None and self.held_expiry is not None:
            if self.Time.date() >= self.held_expiry:
                self.expiration_block_date = self.Time.date()
                if not self.HasOpenExitOrder():
                    self.Debug(
                        f"Expiration safety exit for {self.held_contract} on {self.Time:%Y-%m-%d}"
                    )
                    self.SubmitExit("expiration safety")
                return

        if self.held_contract is not None:
            self.EvaluateExit(slice)

        if self.pending_entry_signal:
            self.pending_entry_signal = False
            self.TryEnter(slice)

    def TryEnter(self, slice):
        if self.held_contract is not None or self.HasOpenEntryOrder() or self.HasOpenExitOrder():
            return

        if self.expiration_block_date == self.Time.date():
            self.Debug("Skipped entry: expiration safety processing is active today.")
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped entry: no SPY option chain in the current Slice.")
            return

        spy_price = float(self.Securities[self.spy].Price)
        if spy_price <= 0:
            self.Debug("Skipped entry: SPY has no valid current price.")
            return

        min_expiry = self.Time.date() + timedelta(days=7)
        contracts = list(chain)

        eligible_expiries = sorted(
            {
                contract.Expiry.date()
                for contract in contracts
                if contract.Expiry.date() >= min_expiry
            }
        )
        if not eligible_expiries:
            self.Debug("Skipped entry: no expiration is at least seven calendar days away.")
            return

        selected_expiry = eligible_expiries[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract
            for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"Skipped entry: no call at or above 101% SPY for {selected_expiry:%Y-%m-%d}."
            )
            return

        selected = min(
            candidates,
            key=lambda c: (float(c.Strike), str(c.Symbol))
        )

        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.held_contract = selected.Symbol
        self.held_expiry = selected.Expiry.date()
        self.entry_price = None

        self.Debug(
            f"Submitted call entry: {selected.Symbol}, strike {selected.Strike}, "
            f"expiry {selected.Expiry:%Y-%m-%d}."
        )

    def EvaluateExit(self, slice):
        if self.HasOpenExitOrder():
            return

        if self.Time.hour == 15 and self.Time.minute == 45:
            preceding_day = self.PreviousSpyTradingDay(self.held_expiry)
            if self.Time.date() == preceding_day:
                self.Debug(f"Time-stop exit for {self.held_contract}.")
                self.SubmitExit("pre-expiration time stop")
                return

        if self.entry_price is None or self.entry_price <= 0:
            return

        midpoint = self.CurrentOptionMidpoint(slice, self.held_contract)
        if midpoint is not None and midpoint >= 1.50 * self.entry_price:
            self.Debug(
                f"Profit-target exit for {self.held_contract}: midpoint {midpoint:.2f}, "
                f"entry {self.entry_price:.2f}."
            )
            self.SubmitExit("profit target")

    def CurrentOptionMidpoint(self, slice, symbol):
        quote_bar = slice.QuoteBars.get(symbol)
        if quote_bar is not None:
            bid = float(quote_bar.Bid.Close)
            ask = float(quote_bar.Ask.Close)
            if bid > 0 and ask > 0:
                return (bid + ask) / 2.0

        # This remains current-Slice data and covers option-chain quote snapshots.
        chain = slice.OptionChains.get(self.option_symbol)
        if chain is not None:
            for contract in chain:
                if contract.Symbol == symbol:
                    bid = float(contract.BidPrice)
                    ask = float(contract.AskPrice)
                    if bid > 0 and ask > 0:
                        return (bid + ask) / 2.0

        return None

    def SubmitExit(self, reason):
        if self.held_contract is None:
            return

        if self.HasOpenExitOrder():
            return

        self.Transactions.CancelOpenOrders(self.held_contract)
        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity != 0:
            ticket = self.MarketOrder(self.held_contract, -quantity)
            self.exit_order_id = ticket.OrderId
            self.Debug(f"Submitted {reason} market exit for {self.held_contract}.")

    def HandleUnexpectedSpyHolding(self):
        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity != 0:
            self.Debug(
                f"Unexpected SPY exercise/assignment holding detected ({spy_quantity}); liquidating."
            )
            self.MarketOrder(self.spy, -spy_quantity)

    def PreviousSpyTradingDay(self, expiry_date):
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        candidate = expiry_date - timedelta(days=1)

        while not exchange_hours.IsDateOpen(
            datetime.combine(candidate, time.min), False
        ):
            candidate -= timedelta(days=1)

        return candidate

    def HasOpenEntryOrder(self):
        if self.entry_order_id is None:
            return False

        ticket = self.Transactions.GetOrderTicket(self.entry_order_id)
        return ticket is not None and ticket.Status not in [
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ]

    def HasOpenExitOrder(self):
        if self.exit_order_id is None:
            return False

        ticket = self.Transactions.GetOrderTicket(self.exit_order_id)
        return ticket is not None and ticket.Status not in [
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ]

    def OnOrderEvent(self, order_event):
        if self.entry_order_id is not None and order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    f"Entry filled for {self.held_contract} at {self.entry_price:.2f}."
                )
                self.entry_order_id = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.Debug(f"Entry order {order_event.OrderId} did not fill.")
                self.entry_order_id = None
                if (
                    self.held_contract is not None
                    and self.Portfolio[self.held_contract].Quantity == 0
                ):
                    self.ResetOptionState()

        if self.exit_order_id is not None and order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled for {self.held_contract} at {float(order_event.FillPrice):.2f}.")
                self.exit_order_id = None
                if (
                    self.held_contract is not None
                    and self.Portfolio[self.held_contract].Quantity == 0
                ):
                    self.ResetOptionState()
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_order_id = None

    def ResetOptionState(self):
        self.held_contract = None
        self.held_expiry = None
        self.entry_price = None
        self.entry_order_id = None
        self.exit_order_id = None
