from AlgorithmImports import *
from datetime import timedelta


class SpyFiveMinuteCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            fillForward=False,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        option = self.AddOption("SPY", Resolution.Minute, fillForward=False)
        option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(0, 730)
        )
        self.option_canonical = option.Symbol

        self.closes = RollingWindow[float](20)
        self.previous_fast = None
        self.previous_slow = None
        self.pending_entry_signal = None

        self.held_contract = None
        self.entry_price = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.spy_exit_order_id = None
        self.block_entry_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        # A 5-minute consolidator on minute SPY data is clock-aligned:
        # the first regular-session bar ends at 09:35 New York time.
        self.closes.Add(float(bar.Close))

        if not self.closes.IsReady:
            return

        fast = sum(self.closes[i] for i in range(5)) / 5.0
        slow = sum(self.closes[i] for i in range(20)) / 20.0

        is_bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        end_time = bar.EndTime.time()
        if is_bullish_cross and (
            (end_time.hour, end_time.minute) >= (9, 45)
            and (end_time.hour, end_time.minute) <= (14, 30)
        ):
            self.pending_entry_signal = bar.EndTime

    def OnData(self, data):
        self._handle_unexpected_spy_position()

        if self.held_contract is not None:
            self._manage_open_option(data)

        # Consolidator events occur before OnData for the same Slice. A signal is
        # evaluated exactly once against the chain delivered with that Slice.
        if self.pending_entry_signal is not None:
            signal_time = self.pending_entry_signal
            self.pending_entry_signal = None

            if signal_time == self.Time:
                self._try_enter(data)

    def _try_enter(self, data):
        if self.block_entry_date == self.Time.date():
            return

        if self._has_open_entry() or self._has_open_exit() or self._has_option_position():
            return

        if self.spy not in data.Bars:
            self.Debug("Entry skipped: SPY has no current minute bar.")
            return

        chain = None
        for candidate in data.OptionChains.Values:
            chain = candidate
            break

        if chain is None:
            self.Debug("Entry skipped: no option chain in current Slice.")
            return

        spot = float(data.Bars[self.spy].Close)
        minimum_expiry = self.Time.date() + timedelta(days=7)

        calls = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        ]

        if not calls:
            self.Debug("Entry skipped: no call expiration satisfies the 7-day rule.")
            return

        expiry = min(contract.Expiry.date() for contract in calls)
        required_strike = spot * 1.01

        eligible = [
            contract for contract in calls
            if contract.Expiry.date() == expiry
            and float(contract.Strike) >= required_strike
        ]

        if not eligible:
            self.Debug("Entry skipped: no eligible 1% OTM call at selected expiry.")
            return

        selected = min(
            eligible,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )

        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.Debug(
            f"Entry submitted: {selected.Symbol} "
            f"expiry {selected.Expiry.date()} strike {selected.Strike}."
        )

    def _manage_open_option(self, data):
        quantity = self.Portfolio[self.held_contract].Quantity

        if quantity == 0:
            self.held_contract = None
            self.entry_price = None
            return

        expiry_date = self.held_contract.ID.Date.date()

        # Do not intentionally carry the contract into its expiration date.
        if self.Time.date() >= expiry_date:
            self.block_entry_date = self.Time.date()
            self._submit_option_exit("expiration processing")
            return

        # Calendar day immediately before expiration, at 15:45 New York time.
        if (
            self.Time.date() == expiry_date - timedelta(days=1)
            and self.Time.hour == 15
            and self.Time.minute == 45
        ):
            self._submit_option_exit("15:45 pre-expiration time stop")
            return

        if self.entry_price is None or self._has_open_exit():
            return

        if self.held_contract not in data.QuoteBars:
            return

        quote = data.QuoteBars[self.held_contract]
        if quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_price * 1.50:
            self._submit_option_exit("50% profit target")

    def _submit_option_exit(self, reason):
        if self.held_contract is None:
            return

        if self._has_open_exit():
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        ticket = self.MarketOrder(self.held_contract, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"Exit submitted: {reason}; {self.held_contract}.")

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        if self._is_order_open(self.spy_exit_order_id):
            return

        ticket = self.MarketOrder(self.spy, -quantity)
        self.spy_exit_order_id = ticket.OrderId
        self.Debug("Unexpected SPY exercise/assignment position detected; liquidation submitted.")

    def OnOrderEvent(self, order_event):
        if order_event.OrderId == self.entry_order_id and order_event.FillQuantity > 0:
            self.held_contract = order_event.Symbol
            self.entry_price = float(order_event.FillPrice)
            self.Debug(
                f"Entry filled: {order_event.Symbol} at {self.entry_price:.2f}."
            )

        if order_event.OrderId == self.entry_order_id and order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            self.entry_order_id = None

        if order_event.OrderId == self.exit_order_id:
            if order_event.FillQuantity != 0:
                self.Debug(
                    f"Exit filled: {order_event.Symbol} at "
                    f"{float(order_event.FillPrice):.2f}."
                )

            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_order_id = None

                if (
                    self.held_contract is not None
                    and self.Portfolio[self.held_contract].Quantity == 0
                ):
                    self.held_contract = None
                    self.entry_price = None

        if order_event.OrderId == self.spy_exit_order_id and order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            self.spy_exit_order_id = None

    def _has_option_position(self):
        return (
            self.held_contract is not None
            and self.Portfolio[self.held_contract].Quantity != 0
        )

    def _has_open_entry(self):
        return self._is_order_open(self.entry_order_id)

    def _has_open_exit(self):
        return self._is_order_open(self.exit_order_id)

    def _is_order_open(self, order_id):
        if order_id is None:
            return False

        ticket = self.Transactions.GetOrderTicket(order_id)
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )
