from AlgorithmImports import *
from datetime import datetime, timedelta, time


class FiveMinuteSpyCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        spy = self.AddEquity("SPY", Resolution.Minute)
        spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = spy.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe.Strikes(-100, 100).Expiration(0, 730)
        )
        self.option_symbol = option.Symbol

        # Manually updated from minute SPY TradeBars, aligned to five-minute
        # New York clock boundaries (09:30-09:35 is the first RTH bar).
        self.five_minute_consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.five_minute_consolidator.DataConsolidated += self.OnFiveMinuteBar

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.entry_signal_pending = False
        self.entry_order_id = None
        self.exit_order_id = None
        self.equity_liquidation_order_id = None

        self.held_contract = None
        self.held_expiry = None
        self.entry_fill_price = None

        self.no_entries_date = None

    def OnData(self, data: Slice):
        if self.no_entries_date != self.Time.date():
            self.no_entries_date = None

        self.HandleUnexpectedSpyPosition()
        self.HandleExpirationSafety()
        self.HandlePositionExits(data)

        # Feed only actual minute TradeBars. Missing bars are never synthesized.
        if data.Bars.ContainsKey(self.spy):
            self.five_minute_consolidator.Update(data.Bars[self.spy])

        # The consolidator callback can set this during the update immediately above.
        if self.entry_signal_pending:
            self.entry_signal_pending = False
            self.TryEnter(data)

    def OnFiveMinuteBar(self, sender, bar: TradeBar):
        previous_fast_ready = self.fast.IsReady
        previous_slow_ready = self.slow.IsReady
        previous_fast = self.fast.Current.Value if previous_fast_ready else None
        previous_slow = self.slow.Current.Value if previous_slow_ready else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        bar_end_time = bar.EndTime.time()
        eligible_time = time(9, 45) <= bar_end_time <= time(14, 30)

        if (
            eligible_time
            and previous_fast_ready
            and previous_slow_ready
            and self.fast.IsReady
            and self.slow.IsReady
            and previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        ):
            self.entry_signal_pending = True

    def TryEnter(self, data: Slice):
        if self.no_entries_date == self.Time.date():
            return

        if self.HasOptionPosition() or self.HasOpenEntryOrder() or self.HasOpenExitOrder():
            return

        if not data.OptionChains.ContainsKey(self.option_symbol):
            self.Debug("Entry skipped: no SPY option chain in current Slice.")
            return

        spy_price = self.Securities[self.spy].Price
        if spy_price <= 0:
            self.Debug("Entry skipped: SPY has no valid current price.")
            return

        chain = data.OptionChains[self.option_symbol]
        minimum_expiry = self.Time.date() + timedelta(days=7)

        valid_expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        })

        if not valid_expiries:
            self.Debug("Entry skipped: no call expiration at least 7 calendar days away.")
            return

        selected_expiry = valid_expiries[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no qualifying OTM call at selected expiration.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.Debug(
            f"Entry submitted: {selected.Symbol} expiry {selected_expiry} "
            f"strike {selected.Strike}"
        )

    def HandlePositionExits(self, data: Slice):
        if not self.HasOptionPosition() or self.held_contract is None:
            return

        # Mandatory time stop on the trading day immediately before expiration.
        if (
            self.Time.date() == self.PreviousTradingDay(self.held_expiry)
            and self.Time.time() == time(15, 45)
        ):
            self.SubmitExit("pre-expiration time stop", replace_existing=True)
            return

        if self.entry_fill_price is None or self.HasOpenExitOrder():
            return

        midpoint = self.GetCurrentOptionMidpoint(data, self.held_contract)
        if midpoint is not None and midpoint >= self.entry_fill_price * 1.50:
            self.SubmitExit("50% profit target", replace_existing=True)

    def HandleExpirationSafety(self):
        if (
            self.HasOptionPosition()
            and self.held_expiry is not None
            and self.Time.date() >= self.held_expiry
        ):
            self.no_entries_date = self.Time.date()
            self.SubmitExit("expiration safety liquidation", replace_existing=True)

    def HandleUnexpectedSpyPosition(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        if self.equity_liquidation_order_id is None or not self.IsOrderOpen(
            self.equity_liquidation_order_id
        ):
            self.no_entries_date = self.Time.date()
            ticket = self.MarketOrder(self.spy, -quantity)
            self.equity_liquidation_order_id = ticket.OrderId
            self.Debug(
                f"Unexpected SPY exercise/assignment position ({quantity}); liquidating."
            )

    def SubmitExit(self, reason: str, replace_existing: bool):
        if self.held_contract is None:
            return

        if self.HasOpenExitOrder():
            if not replace_existing:
                return
            self.Transactions.CancelOrder(self.exit_order_id)

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        ticket = self.MarketOrder(self.held_contract, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"Exit submitted: {reason} for {self.held_contract}")

    def GetCurrentOptionMidpoint(self, data: Slice, symbol: Symbol):
        if not data.QuoteBars.ContainsKey(symbol):
            return None

        quote_bar = data.QuoteBars[symbol]
        if quote_bar.Bid is None or quote_bar.Ask is None:
            return None

        bid = quote_bar.Bid.Close
        ask = quote_bar.Ask.Close

        if bid <= 0 or ask <= 0:
            return None

        return (bid + ask) / 2.0

    def PreviousTradingDay(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def HasOptionPosition(self):
        return (
            self.held_contract is not None
            and self.Portfolio[self.held_contract].Invested
        )

    def HasOpenEntryOrder(self):
        return self.entry_order_id is not None and self.IsOrderOpen(self.entry_order_id)

    def HasOpenExitOrder(self):
        return self.exit_order_id is not None and self.IsOrderOpen(self.exit_order_id)

    def IsOrderOpen(self, order_id):
        if order_id is None:
            return False

        order = self.Transactions.GetOrderById(order_id)
        return order is not None and order.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.UpdateSubmitted
        ]

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled and order_event.FillQuantity > 0:
                self.held_contract = order_event.Symbol
                self.held_expiry = order_event.Symbol.ID.Date.date()
                self.entry_fill_price = order_event.FillPrice
                self.entry_order_id = None
                self.Debug(
                    f"Entry filled: {self.held_contract} at {self.entry_fill_price:.2f}"
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.entry_order_id = None
                self.Debug("Entry order canceled or invalid.")

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order_event.Symbol} at {order_event.FillPrice:.2f}")
                self.exit_order_id = None

                if not self.Portfolio[order_event.Symbol].Invested:
                    self.held_contract = None
                    self.held_expiry = None
                    self.entry_fill_price = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_order_id = None

        if order_event.OrderId == self.equity_liquidation_order_id:
            if order_event.Status in [
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ]:
                self.equity_liquidation_order_id = None
